import { taskDescriptionSchema, taskPrioritySchema, taskTitleSchema } from "@taskflow/validators/tasks";

export const createTaskSchema = z.strictObject({
  projectId: z.uuid(),
  title: taskTitleSchema,
  description: taskDescriptionSchema.nullable().optional(),
  priority: taskPrioritySchema.default("MEDIUM"),
  dueAt: z.iso.datetime().nullable().optional(),
});

export const updateTaskSchema = createTaskSchema.omit({ projectId: true }).partial().refine(
  (value) => Object.keys(value).length > 0,
  { message: "At least one field must be provided." },
);

